import{_ as i,o as a,c as t,ao as r}from"./chunks/framework.DA_3JxoV.js";const b=JSON.parse('{"title":"Public API","description":"","frontmatter":{},"headers":[],"relativePath":"lib/public.md","filePath":"lib/public.md","lastUpdated":null}'),o={name:"lib/public.md"};function l(n,e,s,d,c,P){return a(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="public_api" tabindex="-1">Public API <a class="header-anchor" href="#public_api" aria-label="Permalink to &quot;Public API {#public_api}&quot;">​</a></h1><p>This page is the curated, stable public API surface of MPSKit — the symbols that are exported and intended for direct use. Each entry links to its full docstring in the <a href="/MPSKit.jl/previews/PR449/lib/lib#lib_index">Library</a> index. The category reference pages (<a href="/MPSKit.jl/previews/PR449/lib/states#lib_states">States</a>, <a href="/MPSKit.jl/previews/PR449/lib/operators#lib_operators">Operators</a>, <a href="/MPSKit.jl/previews/PR449/lib/groundstate#lib_groundstate">Ground-state algorithms</a>) group the same docstrings by topic.</p><div class="tip custom-block"><p class="custom-block-title">Note</p><p>Anything not listed here (or marked internal in the <a href="/MPSKit.jl/previews/PR449/lib/lib#lib_index">Library</a> index) is not part of the public API and may change without notice.</p></div><h2 id="States" tabindex="-1">States <a class="header-anchor" href="#States" aria-label="Permalink to &quot;States {#States}&quot;">​</a></h2><p>The matrix product state types — finite, infinite, windowed, and multi-line.</p><p><a href="/MPSKit.jl/previews/PR449/lib/lib#MPSKit.FiniteMPS"><code>FiniteMPS</code></a>, <a href="/MPSKit.jl/previews/PR449/lib/lib#MPSKit.InfiniteMPS"><code>InfiniteMPS</code></a>, <a href="/MPSKit.jl/previews/PR449/lib/lib#MPSKit.WindowMPS"><code>WindowMPS</code></a>, <a href="/MPSKit.jl/previews/PR449/lib/lib#MPSKit.MultilineMPS"><code>MultilineMPS</code></a></p><h2 id="Operators-and-Hamiltonians" tabindex="-1">Operators and Hamiltonians <a class="header-anchor" href="#Operators-and-Hamiltonians" aria-label="Permalink to &quot;Operators and Hamiltonians {#Operators-and-Hamiltonians}&quot;">​</a></h2><p>Matrix product operators and Hamiltonians, finite and infinite, plus the wrappers used to build time-dependent and summed operators.</p><p><a href="/MPSKit.jl/previews/PR449/lib/lib#MPSKit.AbstractMPO"><code>AbstractMPO</code></a>, <a href="/MPSKit.jl/previews/PR449/lib/lib#MPSKit.MPO"><code>MPO</code></a>, <a href="/MPSKit.jl/previews/PR449/lib/lib#MPSKit.FiniteMPO"><code>FiniteMPO</code></a>, <a href="/MPSKit.jl/previews/PR449/lib/lib#MPSKit.InfiniteMPO"><code>InfiniteMPO</code></a>, <a href="/MPSKit.jl/previews/PR449/lib/lib#MPSKit.MultilineMPO"><code>MultilineMPO</code></a>, <a href="/MPSKit.jl/previews/PR449/lib/lib#MPSKit.MPOHamiltonian"><code>MPOHamiltonian</code></a>, <a href="/MPSKit.jl/previews/PR449/lib/lib#MPSKit.FiniteMPOHamiltonian-Tuple{Vector{&lt;:AbstractMatrix}}"><code>FiniteMPOHamiltonian</code></a>, <a href="/MPSKit.jl/previews/PR449/lib/lib#MPSKit.InfiniteMPOHamiltonian-Tuple{Vector{&lt;:AbstractMatrix}}"><code>InfiniteMPOHamiltonian</code></a>, <a href="/MPSKit.jl/previews/PR449/lib/lib#MPSKit.JordanMPOTensor"><code>JordanMPOTensor</code></a>, <a href="/MPSKit.jl/previews/PR449/lib/lib#MPSKit.MultipliedOperator"><code>MultipliedOperator</code></a>, <a href="/MPSKit.jl/previews/PR449/lib/lib#MPSKit.TimedOperator"><code>TimedOperator</code></a>, <a href="/MPSKit.jl/previews/PR449/lib/lib#MPSKit.UntimedOperator"><code>UntimedOperator</code></a>, <a href="/MPSKit.jl/previews/PR449/lib/lib#MPSKit.LazySum"><code>LazySum</code></a></p><h2 id="Environments" tabindex="-1">Environments <a class="header-anchor" href="#Environments" aria-label="Permalink to &quot;Environments {#Environments}&quot;">​</a></h2><p>The caches that store partially contracted tensor networks and are reused throughout the algorithms; see the concept page on <a href="/MPSKit.jl/previews/PR449/concepts/environments#concept_environments">Environments</a> for why they exist.</p><p><a href="/MPSKit.jl/previews/PR449/lib/lib#MPSKit.environments"><code>environments</code></a></p><h2 id="Ground-states-and-boundaries" tabindex="-1">Ground states and boundaries <a class="header-anchor" href="#Ground-states-and-boundaries" aria-label="Permalink to &quot;Ground states and boundaries {#Ground-states-and-boundaries}&quot;">​</a></h2><p>The ground-state search and 2D leading-boundary interface, and the DMRG/VUMPS/IDMRG family of algorithms that implement it.</p><p><a href="/MPSKit.jl/previews/PR449/lib/groundstate#MPSKit.find_groundstate-lib-groundstate"><code>find_groundstate</code></a>, <a href="/MPSKit.jl/previews/PR449/lib/lib#MPSKit.leading_boundary"><code>leading_boundary</code></a>, <a href="/MPSKit.jl/previews/PR449/lib/lib#MPSKit.approximate"><code>approximate</code></a>, <a href="/MPSKit.jl/previews/PR449/lib/lib#MPSKit.VUMPS"><code>VUMPS</code></a>, <a href="/MPSKit.jl/previews/PR449/lib/lib#MPSKit.VOMPS"><code>VOMPS</code></a>, <a href="/MPSKit.jl/previews/PR449/lib/lib#MPSKit.DMRG"><code>DMRG</code></a>, <a href="/MPSKit.jl/previews/PR449/lib/lib#MPSKit.DMRG2"><code>DMRG2</code></a>, <a href="/MPSKit.jl/previews/PR449/lib/lib#MPSKit.IDMRG"><code>IDMRG</code></a>, <a href="/MPSKit.jl/previews/PR449/lib/lib#MPSKit.IDMRG2"><code>IDMRG2</code></a>, <a href="/MPSKit.jl/previews/PR449/lib/lib#MPSKit.GradientGrassmann"><code>GradientGrassmann</code></a></p><h2 id="Bond-dimension" tabindex="-1">Bond dimension <a class="header-anchor" href="#Bond-dimension" aria-label="Permalink to &quot;Bond dimension {#Bond-dimension}&quot;">​</a></h2><p>Expanding or truncating a state&#39;s virtual spaces, and the algorithms that drive it.</p><p><a href="/MPSKit.jl/previews/PR449/lib/lib#MPSKit.changebonds"><code>changebonds</code></a>, <a href="/MPSKit.jl/previews/PR449/lib/lib#MPSKit.OptimalExpand"><code>OptimalExpand</code></a>, <a href="/MPSKit.jl/previews/PR449/lib/lib#MPSKit.RandExpand"><code>RandExpand</code></a>, <a href="/MPSKit.jl/previews/PR449/lib/lib#MPSKit.SvdCut"><code>SvdCut</code></a>, <a href="/MPSKit.jl/previews/PR449/howto/bond_dimension#VUMPSSvdCut"><code>VUMPSSvdCut</code></a></p><h2 id="Time-evolution" tabindex="-1">Time evolution <a class="header-anchor" href="#Time-evolution" aria-label="Permalink to &quot;Time evolution {#Time-evolution}&quot;">​</a></h2><p>Real- and imaginary-time evolution drivers and the algorithms and MPO approximations that implement them.</p><p><a href="/MPSKit.jl/previews/PR449/lib/lib#MPSKit.time_evolve"><code>time_evolve</code></a>, <a href="/MPSKit.jl/previews/PR449/lib/lib#MPSKit.timestep"><code>timestep</code></a>, <a href="/MPSKit.jl/previews/PR449/lib/lib#MPSKit.make_time_mpo"><code>make_time_mpo</code></a>, <a href="/MPSKit.jl/previews/PR449/lib/lib#MPSKit.TDVP"><code>TDVP</code></a>, <a href="/MPSKit.jl/previews/PR449/lib/lib#MPSKit.TDVP2"><code>TDVP2</code></a>, <a href="/MPSKit.jl/previews/PR449/lib/lib#MPSKit.WI"><code>WI</code></a>, <a href="/MPSKit.jl/previews/PR449/lib/lib#MPSKit.WII"><code>WII</code></a>, <a href="/MPSKit.jl/previews/PR449/lib/lib#MPSKit.TaylorCluster"><code>TaylorCluster</code></a></p><h2 id="Excitations" tabindex="-1">Excitations <a class="header-anchor" href="#Excitations" aria-label="Permalink to &quot;Excitations {#Excitations}&quot;">​</a></h2><p>The excitation interface and the quasiparticle-ansatz and finite-excited-state algorithms that produce excited states on top of a ground state.</p><p><a href="/MPSKit.jl/previews/PR449/lib/lib#MPSKit.excitations"><code>excitations</code></a>, <a href="/MPSKit.jl/previews/PR449/lib/lib#MPSKit.FiniteExcited"><code>FiniteExcited</code></a>, <a href="/MPSKit.jl/previews/PR449/lib/lib#MPSKit.QuasiparticleAnsatz"><code>QuasiparticleAnsatz</code></a>, <a href="/MPSKit.jl/previews/PR449/lib/lib#MPSKit.ChepigaAnsatz"><code>ChepigaAnsatz</code></a>, <a href="/MPSKit.jl/previews/PR449/lib/lib#MPSKit.ChepigaAnsatz2"><code>ChepigaAnsatz2</code></a></p><h2 id="Linear-problems-and-spectral-functions" tabindex="-1">Linear problems and spectral functions <a class="header-anchor" href="#Linear-problems-and-spectral-functions" aria-label="Permalink to &quot;Linear problems and spectral functions {#Linear-problems-and-spectral-functions}&quot;">​</a></h2><p>Solving the MPS linear problems behind dynamical/spectral quantities, such as propagators and susceptibilities.</p><p><a href="/MPSKit.jl/previews/PR449/lib/lib#MPSKit.propagator"><code>propagator</code></a>, <a href="/MPSKit.jl/previews/PR449/lib/lib#MPSKit.DynamicalDMRG"><code>DynamicalDMRG</code></a>, <a href="/MPSKit.jl/previews/PR449/lib/lib#MPSKit.NaiveInvert"><code>NaiveInvert</code></a>, <a href="/MPSKit.jl/previews/PR449/lib/lib#MPSKit.Jeckelmann"><code>Jeckelmann</code></a>, <a href="/MPSKit.jl/previews/PR449/lib/lib#MPSKit.exact_diagonalization-Tuple{FiniteMPOHamiltonian}"><code>exact_diagonalization</code></a>, <a href="/MPSKit.jl/previews/PR449/lib/lib#MPSKit.fidelity_susceptibility-Union{Tuple{T}, Tuple{Union{FiniteMPS, InfiniteMPS}, T, AbstractVector{T}}, Tuple{Union{FiniteMPS, InfiniteMPS}, T, AbstractVector{T}, Any}} where T&lt;:MPOHamiltonian"><code>fidelity_susceptibility</code></a></p><h2 id="Observables-and-analysis" tabindex="-1">Observables and analysis <a class="header-anchor" href="#Observables-and-analysis" aria-label="Permalink to &quot;Observables and analysis {#Observables-and-analysis}&quot;">​</a></h2><p>Extracting physical quantities and analysis diagnostics from an MPS — expectation values, correlators, spectra, and entanglement.</p><p><a href="/MPSKit.jl/previews/PR449/lib/lib#MPSKit.expectation_value"><code>expectation_value</code></a>, <a href="/MPSKit.jl/previews/PR449/lib/lib#MPSKit.correlator"><code>correlator</code></a>, <a href="/MPSKit.jl/previews/PR449/lib/lib#MPSKit.variance"><code>variance</code></a>, <a href="/MPSKit.jl/previews/PR449/lib/lib#MPSKit.correlation_length-Tuple{InfiniteMPS}"><code>correlation_length</code></a>, <a href="/MPSKit.jl/previews/PR449/lib/lib#MPSKit.marek_gap-Tuple{InfiniteMPS}"><code>marek_gap</code></a>, <a href="/MPSKit.jl/previews/PR449/lib/lib#MPSKit.transfer_spectrum"><code>transfer_spectrum</code></a>, <a href="/MPSKit.jl/previews/PR449/lib/lib#MPSKit.entropy-Tuple{InfiniteMPS}"><code>entropy</code></a>, <a href="/MPSKit.jl/previews/PR449/lib/lib#MPSKit.entanglement_spectrum"><code>entanglement_spectrum</code></a></p><h2 id="Boundary-conditions" tabindex="-1">Boundary conditions <a class="header-anchor" href="#Boundary-conditions" aria-label="Permalink to &quot;Boundary conditions {#Boundary-conditions}&quot;">​</a></h2><p>Converting an infinite MPO into a finite one of a given length, either wrapping it (periodic) or truncating it (open).</p><p><a href="/MPSKit.jl/previews/PR449/lib/lib#MPSKit.open_boundary_conditions"><code>open_boundary_conditions</code></a>, <a href="/MPSKit.jl/previews/PR449/lib/lib#MPSKit.periodic_boundary_conditions-Union{Tuple{InfiniteMPO{O}}, Tuple{O}, Tuple{InfiniteMPO{O}, Any}} where O"><code>periodic_boundary_conditions</code></a></p><h2 id="Utility" tabindex="-1">Utility <a class="header-anchor" href="#Utility" aria-label="Permalink to &quot;Utility {#Utility}&quot;">​</a></h2><p>Periodic and windowed array containers, virtual/physical space accessors, and a compact &quot;braille&quot; visualization of an MPO&#39;s sparsity structure.</p><p><a href="/MPSKit.jl/previews/PR449/lib/lib#MPSKit.PeriodicArray"><code>PeriodicArray</code></a>, <a href="/MPSKit.jl/previews/PR449/lib/lib#MPSKit.PeriodicVector"><code>PeriodicVector</code></a>, <a href="/MPSKit.jl/previews/PR449/lib/lib#MPSKit.PeriodicMatrix"><code>PeriodicMatrix</code></a>, <a href="/MPSKit.jl/previews/PR449/lib/lib#MPSKit.WindowArray"><code>WindowArray</code></a>, <a href="/MPSKit.jl/previews/PR449/lib/lib#MPSKit.left_virtualspace"><code>left_virtualspace</code></a>, <a href="/MPSKit.jl/previews/PR449/lib/lib#MPSKit.right_virtualspace"><code>right_virtualspace</code></a>, <a href="/MPSKit.jl/previews/PR449/lib/lib#MPSKit.physicalspace"><code>physicalspace</code></a>, <a href="/MPSKit.jl/previews/PR449/lib/lib#MPSKit.braille-Tuple{IO, Union{AbstractMPO{O} where O&lt;:BlockTensorKit.SparseBlockTensorMap, MPOHamiltonian}}"><code>braille</code></a></p>',36)])])}const M=i(o,[["render",l]]);export{b as __pageData,M as default};
